/// Motion. Check accessibilityReduceMotion before animating; nothing moves when it is on.
public enum NearAIMotion {
    public static let durationFast: Double = 0.15
    public static let durationReveal: Double = 0.18
    public static let durationStandard: Double = 0.22
    public static let durationSlide: Double = 0.25
    public static let durationSlow: Double = 0.3
    public static let durationSpin: Double = 0.8
    public static let durationPulse: Double = 1.6
    /// The one curve (ease-standard) for fades, fills, hover and press.
    public static func standard(_ duration: Double = durationStandard) -> Animation {
        .timingCurve(0.2, 0.8, 0.2, 1, duration: duration)
    }
    /// Small spatial moves: a switch knob, a selection indicator, a segment thumb (M3 standard fast spatial).
    public static let springSpatialFast = Animation.spring(response: 0.1679, dampingFraction: 0.9)
    /// Default spatial moves: panes opening, sheets, popovers growing from their source (M3 standard default spatial).
    public static let springSpatial = Animation.spring(response: 0.2375, dampingFraction: 0.9)
    /// Large spatial moves: full-screen and window-level transitions (M3 standard slow spatial).
    public static let springSpatialSlow = Animation.spring(response: 0.3628, dampingFraction: 0.9)
    /// Color, opacity and blur changes that must not overshoot (M3 standard default effects).
    public static let springEffects = Animation.spring(response: 0.1571, dampingFraction: 1)
    /// Hero moments only, one or two per product: a bouncy expressive move (M3 expressive fast spatial).
    public static let springExpressive = Animation.spring(response: 0.2221, dampingFraction: 0.6)
    /// The main-tab ember gliding between tabs (Trace: response 0.35, damping fraction 0.85).
    public static let springEmber = Animation.spring(response: 0.3501, dampingFraction: 0.85)
}

/// One type step on one platform tier.
public struct NearAITypeStep: Sendable {
    public let size: CGFloat
    public let lineHeight: CGFloat
    public let weight: Font.Weight
    public let tracking: CGFloat
    public let textStyle: Font.TextStyle
    public let monospaced: Bool

    /// The step as a system font on its text style, so it follows the person's text size.
    public var font: Font {
        Font.system(textStyle, design: monospaced ? .monospaced : .default).weight(weight)
    }
}

